mod blueprint{#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub struct BlueprintRng{pub seed:u16,pub ring:u8,pub draw_count:u32}}#[path="C:/Users/fallo/Documents/ChatGPT/Freecad/genewars-preflight/rust/crates/genewars-runtime/src/owned_mule_ai.rs"]mod ai;use std::io::{Read,Write};use ai::*;fn main(){let mut data=Vec::new();std::io::stdin().read_to_end(&mut data).unwrap();let mut out=Vec::new();for b in data.chunks_exact(131){let r=&b[..124].try_into().unwrap();let rng=blueprint::BlueprintRng{seed:u16::from_le_bytes([b[124],b[125]]),ring:b[126],draw_count:u32::from_le_bytes(b[127..131].try_into().unwrap())};let c=OwnedIdleContext{neighborhood_eligible:true,current_cell_requires_escape:false};let mut queries=Vec::new();let p=plan_idle_without_building_action(r,rng,c,|s,f,xy|{queries.push((s,f,xy));Ok(None)}).unwrap();assert_eq!(queries.iter().map(|q|q.0).collect::<Vec<_>>(),vec![4,16]);assert!(queries.iter().all(|q|q.1==0x30));assert!(p.continue_common_choice);out.extend(p.after);out.extend(p.rng_after.seed.to_le_bytes());out.push(p.rng_after.ring);out.extend(p.rng_after.draw_count.to_le_bytes());assert_eq!(plan_idle_without_building_action(r,rng,c,|_,_,_|Ok(Some(0))).unwrap_err(),OwnedIdleError::BuildingActionRequired);let mut c2=c;c2.current_cell_requires_escape=true;assert_eq!(plan_idle_without_building_action(r,rng,c2,|_,_,_|Ok(None)).unwrap_err(),OwnedIdleError::CurrentCellActionRequired);let mut c3=c;c3.neighborhood_eligible=false;assert_eq!(plan_idle_without_building_action(r,rng,c3,|_,_,_|Ok(None)).unwrap_err(),OwnedIdleError::UnsupportedState);}std::io::stdout().write_all(&out).unwrap();}